document.getElementById('downloadHtmlButton').addEventListener('click', downloadEditableHtml);
document.getElementById('jsonButton').addEventListener('click', openJsonEditor);
document.getElementById('documentsButton').addEventListener('click', () => document.querySelector('.sidebar').classList.toggle('open'));
document.getElementById('closeSidebarButton').addEventListener('click', () => document.querySelector('.sidebar').classList.remove('open'));
